/** A suggestion for the single-contact form, independent of CSV parsing. */
export function suggestNameFromEmail(email: string): string {
  return email
    .trim()
    .split("@")[0]
    .replace(/[._-]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(" ");
}
